/**
 * BUG-035 残留（最后一条边界）—— 侧车记录**证据范围**，宽域段也能判定刷新。
 *
 * 现象（上一轮收口后仍留）：`// evidence` 之前，侧车只记 `@generated` + `source`，
 * 不记「这段的证据来自哪里」⇒ **调用点来源的宽域段**（`fn({ x: number() },
 * number())`，调用点观测被 BUG-021 拓宽）与「`--from` 采集的使用现场记录来源
 * 段」**逐字同形** ⇒ 调用点被删后宽域段只能保守留存（侧车继续承诺一个今天
 * 已经不存在的域，与 `nudo check` 的签名面矛盾），而误删 `--from` 段又会丢
 * 用户契约。
 *
 * 修法：生成段多一行 `// evidence: local|external` —— 分析器在
 * `FunctionAnalysis.externalEvidence` 上记录「本函数的 callsite 证据是否混入
 * `--from` 外部记录」，发射器落进段头。删除判据（`sectionEvidenceIsInFile`）
 * 改为：无 `derived-from` 标签 **且**（`local` 标记，或旧侧车无标记时的
 * 「单点字面量」启发式）。
 *
 * 钉：① 宽域 **local** 段在调用点消失后被删（残差收口）；
 * ② `--from` 外部记录来源的段带 `external` 标记，且证据缺失时**留存**；
 * ③ 旧侧车（无标记）宽域段仍然留存（迁移期零回归）；
 * ④ 旧侧车单点字面量段仍按旧启发式删除（既有语义不变）；
 * ⑤ `derived-from` 段即使带 `local` 标记也**留存**（root 可能在别的文件）；
 * ⑥ 标记是确定性的：连续两次发射逐字节相同、第二次 `changed === false`。
 */
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtempSync, writeFileSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { emitInterface } from "../interface-emitter.ts";
import { numLit, abs as makeAbs } from "@nudojs/core";

let dir: string;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), "nudo-emit-035-scope-"));
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

/** 有调用点证据 ⇒ 投影出**宽域**（BUG-021 把点观测拓宽到基类型） */
const SRC_WITH_CALL = `export function f(x) {
  return x + 1;
}
f(9);
`;

/** 同一份文件删掉调用点 ⇒ 今天的分析对该导出**完全没有证据** */
const SRC_NO_EVIDENCE = `export function f(x) {
  return x + 1;
}
`;

const HEADER = "// @generated by nudo — do not edit; regenerate with `nudo contract --emit`\n";

/** 上一轮格式（**无** `// evidence:` 行）的宽域段 —— 迁移期必须继续留存 */
const LEGACY_WIDE = `${HEADER}// source: lib.js:f
export const f = fn({ x: number() }, number());
`;

/** 上一轮格式的单点字面量见证段 —— 旧启发式可证 ⇒ 仍应被删 */
const LEGACY_WITNESS = `${HEADER}// source: lib.js:f
export const f = fn({ x: lit(5) }, lit(6));
`;

function fixture(src: string, sidecar: string): { file: string; sidecarPath: string } {
  const file = join(dir, "lib.js");
  writeFileSync(file, src);
  const sidecarPath = join(dir, "lib.nudo.js");
  writeFileSync(sidecarPath, sidecar);
  return { file, sidecarPath };
}

/** 归因到本文件的 `--from` 使用现场记录（域来自调用现场，非模块图闭包） */
function rec(file: string, arg: number) {
  return {
    fnName: "f",
    targetModule: file,
    targetExport: "f",
    argAbs: [numLit(arg)],
    resultAbs: numLit(arg + 1),
    throwsAbs: makeAbs({ k: "never" }, undefined, undefined, "exact"),
    callLoc: { line: 4, column: 0 },
  };
}

describe("BUG-035 证据范围（`// evidence:`）—— 宽域段也能判定刷新", () => {
  it("本地调用点来源的宽域段带 `local` 标记；调用点消失 ⇒ 段被删（残差收口）", async () => {
    const file = join(dir, "lib.js");
    writeFileSync(file, SRC_WITH_CALL);
    const first = await emitInterface(file, { fnNames: ["f"], mode: "add" });
    expect(first.written).toEqual(["f"]);
    const sidecarPath = join(dir, "lib.nudo.js");
    const bytes = readFileSync(sidecarPath, "utf-8");
    // 段头记录了证据范围（本项目分析闭包 ⇒ local）
    expect(bytes).toContain("// evidence: local");
    // 宽域（不是单点字面量）——正是旧启发式判不了的那类
    expect(bytes).toContain("export const f = fn({ x: number() }, number());");

    // 调用点被删 ⇒ 今天的分析完全没有证据；标记 local ⇒ 可证 ⇒ 删段
    writeFileSync(file, SRC_NO_EVIDENCE);
    const second = await emitInterface(file, { mode: "update" });
    expect(second.removed).toEqual(["f"]);
    expect(second.changed).toBe(true);
    expect(readFileSync(sidecarPath, "utf-8")).toBe("");
    expect(
      second.issues.some(
        (i) => i.severity === "info" && i.message.includes("evidence disappeared"),
      ),
    ).toBe(true);
  });

  it("`--from` 外部记录来源的段带 `external` 标记；证据缺失 ⇒ 留存（不误删）", async () => {
    const file = join(dir, "lib.js");
    writeFileSync(file, SRC_NO_EVIDENCE);
    const sidecarPath = join(dir, "lib.nudo.js");
    // 第一次：域证据全部来自使用现场记录（本文件无调用点）
    const first = await emitInterface(file, {
      fnNames: ["f"],
      mode: "add",
      records: [rec(file, 4)],
    });
    expect(first.written).toEqual(["f"]);
    const bytes = readFileSync(sidecarPath, "utf-8");
    expect(bytes).toContain("// evidence: external");
    expect(bytes).toContain("export const f = fn({ x: number() }, number());");

    // 第二次：不再给记录（等价于「本轮没采集使用现场」）⇒ 不得据此删段
    const second = await emitInterface(file, { mode: "update" });
    expect(second.removed).toBeUndefined();
    expect(second.changed).toBe(false);
    expect(readFileSync(sidecarPath, "utf-8")).toBe(bytes);
  });

  it("旧侧车（无 `// evidence:` 行）的宽域段仍然留存 —— 迁移期零回归", async () => {
    const { file, sidecarPath } = fixture(SRC_NO_EVIDENCE, LEGACY_WIDE);
    const r = await emitInterface(file, { mode: "update" });
    expect(r.removed).toBeUndefined();
    expect(r.changed).toBe(false);
    expect(readFileSync(sidecarPath, "utf-8")).toBe(LEGACY_WIDE);
  });

  it("旧侧车的单点字面量见证段仍按旧启发式删除（既有语义不变）", async () => {
    const { file, sidecarPath } = fixture(SRC_NO_EVIDENCE, LEGACY_WITNESS);
    const r = await emitInterface(file, { mode: "update" });
    expect(r.removed).toEqual(["f"]);
    expect(readFileSync(sidecarPath, "utf-8")).toBe("");
  });

  it("`derived-from` 段即使带 `local` 标记也留存（root 可能在别的文件）", async () => {
    const derived = `${HEADER}// source: lib.js:f
// derived-from: root.js:base
// evidence: local
export const f = fn({ x: number() }, number());
`;
    const { file, sidecarPath } = fixture(SRC_NO_EVIDENCE, derived);
    const r = await emitInterface(file, { mode: "update" });
    expect(r.removed).toBeUndefined();
    expect(r.changed).toBe(false);
    expect(readFileSync(sidecarPath, "utf-8")).toBe(derived);
  });

  it("标记是确定性的：连续两次发射逐字节相同，第二次无改动", async () => {
    const file = join(dir, "lib.js");
    writeFileSync(file, SRC_WITH_CALL);
    const first = await emitInterface(file, { fnNames: ["f"], mode: "add" });
    expect(first.changed).toBe(true);
    const sidecarPath = join(dir, "lib.nudo.js");
    const bytes = readFileSync(sidecarPath, "utf-8");
    const second = await emitInterface(file, { mode: "update" });
    expect(second.changed).toBe(false);
    expect(second.written).toEqual([]);
    expect(readFileSync(sidecarPath, "utf-8")).toBe(bytes);
  });

  it("存在边界：有外部记录参与但仍有本地证据 ⇒ 标记 external（保守方向 = 少删）", async () => {
    const file = join(dir, "lib.js");
    writeFileSync(file, SRC_WITH_CALL);
    const r = await emitInterface(file, {
      fnNames: ["f"],
      mode: "add",
      records: [rec(file, 4)],
    });
    expect(r.written).toEqual(["f"]);
    expect(readFileSync(join(dir, "lib.nudo.js"), "utf-8")).toContain("// evidence: external");
  });
});
